param([string]$Path='docs/openapi-v14-canonical.json',[string]$EntryPoint='backend/SanSo.Api.V6/ProgramCanonicalV14.cs')
$ErrorActionPreference='Stop';$raw=Get-Content -LiteralPath $Path -Raw -Encoding UTF8;$source=Get-Content -LiteralPath $EntryPoint -Raw -Encoding UTF8;$d=$raw|ConvertFrom-Json;if($d.info.version-ne'0.14.0-pilot'-or$d.'x-sanso-canonical-entrypoint'-ne$EntryPoint){throw 'OPENAPI_V14_HEADER_INVALID'};if(-not$source.Contains('PostgresReportExportStoreV2')-or-not$source.Contains('b.Type')){throw 'REPORT_V2_NOT_IN_SOURCE'};if($null-ne$d.paths.'/api/imports/settlements/direct'){throw 'DEVELOPMENT_ROUTE_EXPOSED'};$types=@($d.components.schemas.ExportRequest.properties.type.enum);if($types.Count-ne2-or-not($types-contains'RECONCILIATION_XLSX')){throw 'EXPORT_TYPES_INVALID'};$refs=[regex]::Matches($raw,'"\$ref"\s*:\s*"#/components/([^/]+)/([^"/]+)"');foreach($m in $refs){if($null-eq$d.components.($m.Groups[1].Value).($m.Groups[2].Value)){throw "BROKEN_REF:$($m.Value)"}};"OPENAPI_V14_VERIFIED paths=$(@($d.paths.PSObject.Properties).Count) refs=$($refs.Count) exportTypes=$($types.Count) directPublic=false"
